export function getGradeContent(grade: number): Record<string, UnitData[]> {
  if (grade === 0) {
    return mergeGradeContents([
      GRADE1_CONTENT,
      GRADE2_CONTENT,
      GRADE3_CONTENT,
      GRADE4_CONTENT,
      GRADE5_CONTENT,
      GRADE6_CONTENT,
      GRADE7_CONTENT,
      GRADE8_CONTENT,
      GRADE9_CONTENT,
    ])
  }
  if (grade === 1) return GRADE1_CONTENT
  if (grade === 2) return GRADE2_CONTENT
  if (grade === 3) return GRADE3_CONTENT
  if (grade === 4) return GRADE4_CONTENT
  if (grade === 5) return GRADE5_CONTENT
  if (grade === 6) return GRADE6_CONTENT
  if (grade === 7) return GRADE7_CONTENT
  if (grade === 8) return GRADE8_CONTENT
  if (grade === 9) return GRADE9_CONTENT
  return GRADE7_CONTENT
}
